#include <iostream>
#include <functional>
#include <random>
#include <chrono>
using namespace std;
struct MyFunctor {
  int operator()(int x, int y) const { return x + y; }
};
int add(int x, int y) { return x + y; }
int main() {
  auto lambda = [](int x, int y){ return x * y; };
  MyFunctor functor;

  cout << "Functor: " << invoke(functor, 5, 3) << endl; // Compile-time dispatch
  cout << "Function: " << invoke(add, 5, 3) << endl;     // Compile-time dispatch
  cout << "Lambda: " << invoke(lambda, 5, 3) << endl;   // Compile-time dispatch

  //Demonstrating with a random number generator (URNG) for context similarity to the prompt
  mt19937_64 gen(chrono::system_clock::now().time_since_epoch().count());
  auto uniform_dist = uniform_int_distribution<int>(1,10);
  cout << "Random generated number (via invoke and lambda) : " << invoke(lambda, uniform_dist(gen), 5) << endl; 
  return 0;
}
//Note: the compiler will inline these calls if optimization is enabled, leading to near-zero overhead.
